#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up Fox Renard's deployments on Cloudflare (docs/deploy.md):
#   bash scripts/setup-deploy.sh
# It writes no secret to disk: each goes straight to GitHub. The account and
# project IDs, which are not secret, stay in .env.deploy for the next run.
# A ticket that needs one more secret adds a stage before "Turn deployments on".

# github_has_secret NAME succeeds when the repository already holds that secret.
github_has_secret() {
  gh secret list --json name --jq '.[].name' 2>/dev/null | grep -qx "$1"
}

# keep_secret NAME offers to keep a secret set by an earlier run.
keep_secret() {
  github_has_secret "$1" && confirm "GitHub already holds $1. Keep it?"
}

run_wizard() {

TOTAL_STAGES=11
ENV_FILE=".env.deploy"
cd "$(git rev-parse --show-toplevel)"

if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "This wizard stores every value in GitHub with the gh CLI."
  say "Install it (https://cli.github.com), run gh auth login, then run this wizard again."
  exit 1
fi
if ! command -v openssl >/dev/null 2>&1; then
  warn "This wizard generates the fingerprint secrets with openssl: install it first."
  exit 1
fi

banner "Deploy Fox Renard to Cloudflare"

stage "Cloudflare: foxrenard.com"
say "Fox Renard runs on Cloudflare under foxrenard.com, so the domain's DNS moves there."
open_url "https://dash.cloudflare.com/sign-up"
step "Sign up, or log in."
step "Add the domain foxrenard.com, on the Free plan."
step "At your registrar, replace foxrenard.com's nameservers with the two Cloudflare shows."
note "Cloudflare emails you once foxrenard.com is Active, which can take up to a day."
note "Carry on meanwhile: only the last stage needs it."
pause "Added foxrenard.com? Press Enter"

stage "Cloudflare: workers.dev subdomain and account ID"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "If Cloudflare asks for one, choose your workers.dev subdomain."
note "Each pull request's preview answers on pr-<number>-fox-renard.<subdomain>.workers.dev."
step "Under Account Details, copy the Account ID."
while ask CLOUDFLARE_ACCOUNT_ID "Paste the account ID:" || exit 1
  [[ ! "$CLOUDFLARE_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]]; do
  warn "An account ID is 32 hexadecimal characters."
done
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
note "Its GitHub variable comes last: setting it turns deployments on."

stage "Cloudflare: API token for CI"
if ! keep_secret CLOUDFLARE_API_TOKEN; then
  open_url "https://dash.cloudflare.com/?to=/:account/api-tokens"
  step "Select Create Token. Under Permission policies, open the Custom dropdown and select Edit Cloudflare Workers."
  step "Add two permissions: Account · Hyperdrive · Edit, and Zone · DNS · Edit."
  step "Scope it to your account, and to the zone foxrenard.com only."
  step "Create the token and copy it."
  note "Hyperdrive: CI points each deployment at its database. DNS: the first deploy creates embed.foxrenard.com."
  ask_secret CLOUDFLARE_API_TOKEN "Paste the API token:"
  set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
fi

stage "Neon: the production database"
if ! keep_secret DATABASE_URL; then
  open_url "https://console.neon.tech/signup"
  step "Sign up, then create a project named fox-renard."
  step "Choose Postgres 17 and the region AWS Europe (Frankfurt), aws-eu-central-1."
  step "Select Connect, turn off Connection pooling, and copy the connection string."
  note "Hyperdrive pools connections itself, and migrations need a direct connection."
  while ask_secret DATABASE_URL "Paste the connection string:" || exit 1
    [[ ! "$DATABASE_URL" =~ ^postgres(ql)?:// || "$DATABASE_URL" == *-pooler.* ]]; do
    warn "Paste the direct connection string: postgresql://…, with no -pooler in its host."
  done
  set_secret DATABASE_URL "$DATABASE_URL"
fi

stage "Neon: the preview project"
say "Each pull request's preview gets a branch of a second project, so no"
say "production data ever reaches a preview (ADR-0008)."
open_url "https://console.neon.tech/app/projects"
step "Create a project named fox-renard-previews, with the same Postgres version and region."
step "In its Settings, copy the Project ID."
ask NEON_PREVIEW_PROJECT_ID "Paste the project ID:"
write_env NEON_PREVIEW_PROJECT_ID "$NEON_PREVIEW_PROJECT_ID"
set_var NEON_PREVIEW_PROJECT_ID "$NEON_PREVIEW_PROJECT_ID"

stage "Neon: an API key for previews"
if ! keep_secret NEON_API_KEY; then
  open_url "https://console.neon.tech"
  step "Switch to your organization, then open Settings, API keys, and select Create new."
  step "Choose Project-scoped, for the project fox-renard-previews, and copy the key."
  note "CI creates and deletes the preview branches with it. It reaches no other project."
  ask_secret NEON_API_KEY "Paste the API key:"
  set_secret NEON_API_KEY "$NEON_API_KEY"
fi

stage "Recto Verso's Member in production"
if ! keep_secret SEED_MEMBER_EMAIL; then
  say "The seed makes this person a Member of Recto Verso's Organization in production."
  note "The address stays a GitHub secret, out of the repository and out of logs."
  while ask SEED_MEMBER_EMAIL "The Member's email:" || exit 1
    [[ "$SEED_MEMBER_EMAIL" != ?*@?*.?* ]]; do
    warn "That doesn't look like an email address."
  done
  set_secret SEED_MEMBER_EMAIL "$SEED_MEMBER_EMAIL"
fi

stage "Generated secrets"
say "This stage generates the secrets nobody needs to see, one for production"
say "and one for previews of each:"
note "the fingerprint secret, which Core derives each day's fingerprint key from (ADR-0006);"
note "the ALTCHA key, which signs the bot check's challenges."
note "Replacing one only resets the day's abuse limits, or the challenges under way."
for name in FINGERPRINT_SECRET PREVIEW_FINGERPRINT_SECRET ALTCHA_HMAC_KEY PREVIEW_ALTCHA_HMAC_KEY; do
  keep_secret "$name" || set_secret "$name" "$(openssl rand -hex 32)"
done

stage "Brevo: account and API key"
if ! keep_secret BREVO_API_KEY; then
  open_url "https://www.brevo.com"
  step "Sign up for the Free plan, or log in."
  open_url "https://app.brevo.com/settings/keys/api"
  step "Under API keys, select Generate a new API key, name it fox-renard, and copy it."
  ask_secret BREVO_API_KEY "Paste the API key:"
  set_secret BREVO_API_KEY "$BREVO_API_KEY"
fi
warn "Leave Security → Authorized IPs → Block unknown IP addresses turned off:"
note "Cloudflare sends from many addresses, so Brevo would block the Worker's emails."
pause "Press Enter"

stage "Brevo: the mail.foxrenard.com sender"
say "Every email comes from noreply@mail.foxrenard.com, once Brevo has"
say "authenticated mail.foxrenard.com with records in Cloudflare's DNS."
open_url "https://app.brevo.com"
step "Open Senders, Domains & Dedicated IPs, then Domains, and add the domain mail.foxrenard.com."
step "If Brevo offers to authenticate it automatically with Cloudflare, accept, and skip the next two steps."
open_url "https://dash.cloudflare.com/?to=/:account/:zone/dns/records"
step "Otherwise, add each record Brevo lists (its code, DKIM, DMARC, and SPF if listed) to foxrenard.com, as DNS only."
note "Copy each record's type, name and value exactly as Brevo shows them."
step "Back in Brevo, select Authenticate."
step "Then, under Senders, add the sender Fox Renard <noreply@mail.foxrenard.com>."
note "On an authenticated domain, Brevo verifies a sender without emailing it a code."
pause "Authenticated? Brevo can take up to 48 hours. Press Enter"

stage "Turn deployments on"
say "Setting the variable CLOUDFLARE_ACCOUNT_ID turns deployments on: merging to"
say "main deploys production, and each pull request gets a preview."
note "The first deployment creates embed.foxrenard.com, so foxrenard.com must be Active."
note "console.foxrenard.com stays free for the Member console."
if confirm "Is foxrenard.com Active on Cloudflare, and should deployments start?"; then
  set_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  if confirm "Deploy main to production now?"; then
    gh workflow run ci.yml --ref main
    note "Follow it with: gh run watch"
  fi
else
  SKIPPED+=("GitHub variable CLOUDFLARE_ACCOUNT_ID, once foxrenard.com is Active: run this wizard again")
fi

finish
}

run_wizard "$@"; exit
